"""Generate a scoped results report and manuscript section from the evidence ledger."""
import json,collections,hashlib,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];B=R/'substantive_evaluation'
def main():
 a=json.loads((B/'analysis.json').read_text());es=json.loads((B/'episode_results.json').read_text());labels=json.loads((B/'labels.json').read_text());timing=json.loads((B/'sampled_timing.json').read_text());ev='substantive_evaluation/episodes';co=next(c for c in a['cohorts'] if c['cohort']==ev);ee=[e for e in es if e['cohort']==ev and e['status']=='completed'];vi=[e for e in ee if e['selected_rule_label']=='violation'];strict=[e for e in vi if not e['interaction_violation'] and not e['policy_tool_discrepancy']];lv=[r for r in labels if r['cohort']==ev and r['candidate_label']=='violation_candidate'];v=json.loads((B/'label_verification.json').read_text());planned=json.loads((B/'protocol.json').read_text())['episodes'];complete=co['attempted']==planned and all(e['status']!='started' for e in es if e['cohort']==ev)
 title='Substantive-policy evaluation: '+('completed collection' if complete else 'interim collection')
 lines=['# '+title,'','This is an exploratory extension on upstream training tasks. Task IDs are new to collection; task templates and entities are not assumed independent. Literal rule checks are software-verified, not human semantic adjudication.','',f"Planned: {planned}; records: {co['attempted']}; completed: {co['completed']}; unfinished or interrupted: {co['attempted']-co['completed']}. New task IDs: {co['task_ids']}. Whole-conversation interaction-clean completions: {co['interaction_clean_completed']}.",'',f"Selected six-rule episode labels: {co['selected_rule_labels']}. An inapplicable record contains no proposed action covered by these six checks; it is not evidence of comprehensive compliance.",'',f"Violation candidates: {len(vi)} completed conversations, {len({e['task'] for e in vi})} task IDs. Candidates remaining after excluding all interaction violations and policy–tool discrepancies: {len(strict)} conversations, {len({e['task'] for e in strict})} task IDs.",'',f"Independent implementation checks: {v['checked_rows']} rule rows; disagreements: {len(v['disagreements'])}. Human adjudication: not performed.",'',f"Across pilot and extension, expected monitor calls: {a['expected_scores']}; valid: {a['scored']}; missing or not yet attempted: {a['missing_or_unattempted']}.",'','## Matched target comparisons','','Each entry averages broad-minus-substantive alert differences within a task, then weights tasks equally. Positive values mean more broad-target alerts. All three targets must have valid scores on a prefix. Scores use a fixed 0.5 threshold and the same retrospective/current-proposal horizon. These are differences between monitor configurations, not an estimate of target-independent accuracy.','','| Monitor | Subset | Matched prefixes | Tasks | Alert difference | Leave-one-task-out range |','|---|---|---:|---:|---:|---|']
 for x in a['comparisons']:
  if x['cohort']==ev and x['threshold']==.5 and x['difference']=='broad minus substantive':
   value='undefined' if x['mean'] is None else f"{100*x['mean']:.1f} pp";loo=x['leave_one_task_out'];lines.append(f"| {x['model']} | {x['subset']} | {x['matched_prefixes']} | {x['n_tasks']} | {value} | {loo} |")
 lines+=['','Task bootstrap intervals and threshold sensitivity are in analysis.json. Entity-linked component sensitivity is in entity_sensitivity.json. Degenerate intervals do not demonstrate population certainty.','', '## Alerts on final-state-matching, selected-rule-clean episodes','','These denominators require at least one applicable selected constraint and no unknown/violating selected-rule labels. They do not certify all natural-language policies. Broad-target alerts may correctly concern an unmeasured rule. Bounds retain missing monitor scores.','','| Monitor | Subset | Target | Negative episodes | Task IDs | Alert count bounds |','|---|---|---|---:|---:|---|']
 for x in a['conditional_negative_alerts']:
  if x['cohort']==ev:lines.append(f"| {x['model']} | {x['subset']} | {x['target']} | {x['negative_episodes']} | {x['negative_tasks']} | {x['alert_count_bounds']} |")
 lines+=['','## Candidate evidence','','| Episode | Rule | Proposal | Tool result | Interaction violation anywhere | Policy–tool discrepancy |','|---|---|---:|---|---|---|']
 byep={e['episode']:e for e in es}
 for r in lv:
  e=byep[r['episode']];lines.append(f"| {r['episode']} | {r['rule']} | {r['message_index']} | {'rejected' if r['tool_error_flag'] else 'returned without error' if r['tool_error_flag'] is False else 'unobserved'} | {e['interaction_violation']} | {r['policy_tool_discrepancy']} |")
 lines+=['','## Interpretation and remaining limits','','The result can support a matched-input diagnosis of target-dependent alerts on the evaluated mechanical constraints. It cannot establish comprehensive policy compliance, calibrated risk, deployment harm prevention, or unseen-domain generalization. Changes to the requested target also change prompt wording; this is a comparison of declared monitor configurations, not a wording-invariant causal effect.','', 'Timing is evaluated only at sampled windows immediately before, at, and after a selected proposal. An alert after the proposal or execution is not credited as prevention. Before-proposal alerts may concern another issue; they are not automatically successful prediction.','', 'If no selected-rule violations remain in the strict subset, substantive-violation detection sensitivity is undefined, not zero and not proven high. Differences in alerts on clean or inapplicable inputs do not repair that missing positive class. Contextual cancellation eligibility, compensation, and explicit authorization remain outside the executable label set. The blinded review packet is still pending. No model output has been represented as human review.','', 'The fixed allocation has not been enlarged because of favorable results, significance, or a desired number of violations. API cost is not the present scientific bottleneck.','', '## Reproduction','','```sh','.venv/bin/python -m unittest substantive_evaluation.test_evaluation substantive_audit.test_audit','.venv/bin/python substantive_evaluation/verify_labels.py','.venv/bin/python substantive_evaluation/analyze.py','.venv/bin/python -m substantive_evaluation.dependence','.venv/bin/python substantive_evaluation/build_report.py','```','', 'Existing paper/main.tex and the submission ZIP remain the earlier package until the expanded manuscript is explicitly integrated and rechecked.']
 (B/'report.md').write_text('\n'.join(lines)+'\n')
 # Tables contain generated counts only; manuscript prose explicitly scopes labels.
 tex=[r'\section{Prospective substantive-rule extension}',r'\label{sec:substantive_extension}',f'A further locally frozen exploratory allocation selected {co["task_ids"]} previously uncollected upstream-training task IDs by a deterministic hash, with two actors and two runs per actor ({planned} planned conversations). {co["completed"]} completed conversations are analyzed separately from the 24-attempt feasibility pilot. These IDs are disjoint from prior collection, but shared entities and workflow templates remain possible. Both actors receive the same interaction-format reminder; native substantive policies and customer scenarios are unchanged.',r'We check six explicitly bounded predicates: airline basic-economy itinerary changes, passenger-count changes and baggage removal; retail order status, refund destination and same-product item changes. A separately implemented reverse-prefix checker validates the executable predicates. Unknown observations are retained. This is software verification of literal constraints, not human adjudication of contextual cancellation eligibility, compensation or authorization.',f'{len(vi)} completed conversations across {len({e["task"] for e in vi})} task IDs contain a selected-rule violation candidate. After excluding entire conversations with an interaction-format violation or a policy--tool discrepancy, {len(strict)} conversations across {len({e["task"] for e in strict})} task IDs remain. Rejected proposals are separated from tool-accepted changes; neither is assumed to establish deployment harm.',r'Two monitor configurations receive identical public inputs under three requested targets: any public-policy violation, the interaction-format rule, or the six selected substantive constraints. All prompts ask whether a violation has already occurred or is currently proposed. This shared horizon avoids conflating target changes with future-failure prediction. We score the nearest generated assistant prefixes before, at and after every applicable proposal, deduplicating overlaps. Timing claims concern these sampled windows only.',r'\begin{table}[t]\centering\small',r'\caption{Prospective extension: task-weighted broad-minus-substantive alert differences at threshold 0.5 on matched valid inputs, after excluding all interaction-violating conversations and policy--tool discrepancies. Percentage points describe configuration differences, not target-independent error rates.}',r'\begin{tabular}{lrrr}\toprule Monitor & Prefixes & Tasks & Difference (pp) \\\midrule']
 for x in a['comparisons']:
  if x['cohort']==ev and x['threshold']==.5 and x['difference']=='broad minus substantive' and x['subset']=='interaction_clean_no_policy_tool_discrepancy':tex.append(f"{x['model']} & {x['matched_prefixes']} & {x['n_tasks']} & "+('undefined' if x['mean'] is None else f"{100*x['mean']:.1f}")+r' \\')
 tex +=[r'\bottomrule\end{tabular}\end{table}',r'Task-level leave-one-out and visible-entity-component sensitivity are reported in the executable artifact. A clean label certifies only the applicable selected predicates, not all policy requirements. Consequently, alerts on these negatives are proxy-relative; broad-target alerts can be correct for unmeasured requirements. Upstream training exposure, shared entities, limited violating-task support and pending contextual adjudication restrict generalization.']
 dep=json.loads((B/'dependency_inventory.json').read_text())
 tex.insert(4, f"The extension contains {dep['new_reference_sequence_groups']} distinct exact reference-operation sequences, a coarse proxy rather than a semantic family definition. {dep['new_tasks_with_visible_entity_overlap']} of its 24 task IDs share visible users, orders or reservations with earlier collection. Of {a['expected_scores']} prespecified monitor cells across pilot and extension, {a['scored']} have valid outputs and the number of unavailable scores is {a['missing_or_unattempted']}.")
 for model in ['gemini','gptmini']:
  row=next(x for x in a['comparisons'] if x['cohort']==ev and x['subset']=='interaction_clean_no_policy_tool_discrepancy' and x['model']==model and x['threshold']==.5 and x['difference']=='broad minus substantive')
  lo=row['leave_one_task_out']
  if lo is not None:tex.append(f"For { {'gemini':'Gemini 3.8 Flash','gptmini':'GPT-5.4 Mini'}[model]}, deleting any one task leaves the broad-minus-substantive difference between {100*lo[0]:.1f} and {100*lo[1]:.1f} percentage points.")
 negatives={(x['model'],x['target']):x for x in a['conditional_negative_alerts'] if x['cohort']==ev and x['subset']=='interaction_clean_no_policy_tool_discrepancy'}
 nb=negatives['gemini','broad'];ns=negatives['gemini','substantive'];gb=negatives['gptmini','broad'];gs=negatives['gptmini','substantive']
 tex.append(f"In the stricter final-state-matching negative class, {nb['negative_episodes']} conversations from {nb['negative_tasks']} tasks are clean for the selected constraints and interaction format. Gemini alerts on {nb['alert_count_bounds'][0]}/{nb['negative_episodes']} with the broad target and {ns['alert_count_bounds'][0]}/{ns['negative_episodes']} with the substantive target; GPT-5.4 Mini alerts on {gb['alert_count_bounds'][0]}/{gb['negative_episodes']} and {gs['alert_count_bounds'][0]}/{gs['negative_episodes']}, respectively. These descriptive rates do not identify every broad alert as an error because unmeasured policy requirements remain. The observed directions do not justify a universal claim that narrowing the target reduces alerts.")
 if not strict:tex.append('The strict subset has no positive selected-rule examples; its violation-detection sensitivity is therefore undefined. Alert differences on negative examples do not establish detection of substantive violations across tasks.')
 (B/'manuscript_section.tex').write_text('\n\n'.join(tex).replace('gemini &','Gemini 3.8 Flash &').replace('gptmini &','GPT-5.4 Mini &')+'\n')
 print(json.dumps({'report':str(B/'report.md'),'collection_complete':complete,'strict_candidate_tasks':len({e['task'] for e in strict})}))
if __name__=='__main__':main()
